def main() -> None:
    en = {e["id"]: e for e in json.loads((KB / "entries.en.json").read_text(encoding="utf-8"))}
    out = []
    for key, (section, q, alts, ans) in P.items():
        base = en.get(key)
        doc = base["document"] if base else {"pp-lost": "nis-passports", "gen-misuse": "about-assistant"}[key]
        out.append({"id": key, "document": doc, "section_title": section, "question_text": q, "alt_questions": alts, "answer_text": ans})
    missing = set(en) - set(P)
    assert not missing, f"Pidgin layer is missing: {sorted(missing)}"
    (KB / "entries.pcm.json").write_text(json.dumps(out, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"wrote {len(out)} Pidgin entries")


if __name__ == "__main__":
    main()
